INSERT INTO clinlims.observation_history_type (id, type_name, description, lastupdated)
SELECT nextval('clinlims.observation_history_type_seq'), 'TbPatientNumber', 'TB_PATIENT_NUMBER', now()
WHERE NOT EXISTS (SELECT 1 FROM clinlims.observation_history_type WHERE type_name = 'TbPatientNumber');
INSERT INTO clinlims.observation_history_type (id, type_name, description, lastupdated)
SELECT nextval('clinlims.observation_history_type_seq'), 'TbSuspectNumber', 'TB_SUSPECT_NUMBER', now()
WHERE NOT EXISTS (SELECT 1 FROM clinlims.observation_history_type WHERE type_name = 'TbSuspectNumber');
